package TCP;
import java.io.*;
import java.net.*;

import java.io.Serializable;

public class Student implements Serializable {
    private static final long serialVersionUID = 20150711L;

    private int id;
    private String code;
    private float gpa;
    private int gpaLetter;

    public Student(){}
    public Student(int id, String code, float gpa, int gpaLetter) {
        this.id = id;
        this.code = code.toUpperCase();
        this.gpa = gpa;
        if (gpa >= 3.6) { this.gpaLetter = 'A'; }
        else if (gpa >= 3.2) { this.gpaLetter = 'B'; }  
        else if (gpa >= 2.5) { this.gpaLetter = 'C'; }
        else if (gpa >= 2.0) { this.gpaLetter = 'D'; }
        else { this.gpaLetter = 'F'; }
    }

    public int getId() {
        return id;
    }

    public String getCode() {
        return code;
    }

    public float getGpa() {
        return gpa;
    }

    public int getGpaLetter() {
        return gpaLetter;
    }

    public void setId(int id) {
        this.id = id;
    }

    public void setCode(String code) {
        this.code = code;
    }

    public void setGpa(float gpa) {
        this.gpa = gpa;
    }

    public void setGpaLetter(int gpaLetter) {
        this.gpaLetter = gpaLetter;
    }

    public static void main(String[] args) throws Exception {
        DatagramSocket socket = new DatagramSocket();
        InetAddress address = InetAddress.getByName("localhost");
        int port = 2209;

        String studentCode = "B15DCCN001";
        String qCode = "EE29C059";
        String message = ";" + studentCode + ";" + qCode;
        byte[] sendData = message.getBytes();

        DatagramPacket sendPacket = new DatagramPacket(sendData, sendData.length, address, port);
        socket.send(sendPacket);

        byte[] receiveData = new byte[4096];
        DatagramPacket receivePacket = new DatagramPacket(receiveData, receiveData.length);
        socket.receive(receivePacket);

        byte[] data = receivePacket.getData();
        int length = receivePacket.getLength();
        ByteArrayInputStream bais = new ByteArrayInputStream(data, 0, length);
        ObjectInputStream ois = new ObjectInputStream(bais);
        Student student = (Student) ois.readObject();
        ois.close();

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(baos);
        oos.writeObject(student);
        oos.flush();

        byte[] objectData = baos.toByteArray();
        ByteArrayOutputStream result = new ByteArrayOutputStream();
        result.write(objectData);
        byte[] resultData = result.toByteArray();
        DatagramPacket responsePacket = new DatagramPacket(resultData, resultData.length, receivePacket.getAddress(), receivePacket.getPort());
        socket.send(responsePacket);
        oos.close();
        socket.close();
    }
}

